  if (els.length === 1 && charge === 0) return { kind: 'element', text: 'element: oxidation state 0', st: { [els[0]]: 0 } };
  if (els.every(e => EL[e].en < 2.0 && !['H', 'B', 'Si', 'Ge', 'Sb', 'Te', 'As'].includes(e)) && charge === 0) return { kind: 'metallic', text: 'all constituents are metals: alloy or intermetallic, no ionic charge balance expected' };
