function parseSide(t) { return String(t).split(/\s\+\s/).map(s => s.trim()).filter(Boolean).map(s => { const s2 = s.replace(/^\d+(\.\d+)?\s+/, ''), ph = s2.match(/\((s|l|g|aq)\)$/); return { f: ph ? s2.slice(0, ph.index) : s2, phase: ph ? ph[1] : '' }; }); }
