// ---------- mode: substitution and supply risk ----------
function runSubst(inp) {
  const m = getMat(inp.matId), p = m.props || {}, W = [], tol = inp.tolBand / 100, keys = ['density', 'E', 'k_thermal', 'cte', 'bandgap_eV', 'n_refr', 'sigma_elec', 'eps_r'].filter(k => num(p[k]) !== null && p[k] !== 0);
  let pool = MATERIALS.filter(x => x.classId === m.classId && x.id !== m.id), scope = 'same class';
  if (pool.length < 2) { pool = MATERIALS.filter(x => x.id !== m.id && x.kind === m.kind && x.dimensionality === m.dimensionality); scope = 'same kind and dimensionality (class has fewer than two other members)'; }
  const alts = pool.map(x => { const q = x.props || {}; let inb = 0, cmp = 0, d = 0; const det = []; for (const k of keys) { const v = num(q[k]); if (v === null) continue; cmp++; const rel = (v - p[k]) / Math.abs(p[k]); if (Math.abs(rel) <= tol) inb++; d += Math.abs(rel); det.push(`${k} ${rel >= 0 ? '+' : ''}${F(100 * rel, 3)} %`); } return { x, inb, cmp, dist: cmp ? d / cmp : Infinity, det }; }).filter(a => a.cmp > 0).sort((a, b) => b.inb / b.cmp - a.inb / a.cmp || a.dist - b.dist);
  const full = alts.filter(a => a.inb === a.cmp);
  const f = formulaOf(m), q = f ? safeParse(f) : null, els = q ? Object.keys(q.atoms) : [], M = q ? chem.molarMass(q) : 0, ox = q ? oxStates(q.atoms, 0) : null;
  const crm = els.filter(e => CRM[e]), haz = els.filter(e => HAZ[e]), wCrm = q ? N.sum(crm.filter(e => e !== 'C').map(e => EL[e].mass * q.atoms[e] / M)) : 0, wHaz = q ? N.sum(haz.map(e => EL[e].mass * q.atoms[e] / M)) : 0;
  if (!q) W.push('This entry has no stoichiometric formula (alloy grade, polymer blend or architecture): elemental screening is not possible; check the constituent and precursor list manually.');
  if (els.includes('Cr') && ox && ox.st && ox.st.Cr === 6) W.push('Chromium is in the +6 state in this formula: hexavalent chromium is carcinogenic and restricted.');
  W.push('Critical-raw-material flags follow a screening list based on the EU 2023 list; verify against the current official list for your jurisdiction. Hazard flags are element-based and do not replace the safety data sheet.');
  // thermal-mismatch compatibility with the chosen substrate
  const sub = getMat(inp.subId), sp = sub.props || {}, dT = inp.dT, aM = num(p.cte), aS = num(sp.cte), eps = aM !== null && aS !== null ? (aS - aM) * dT : null, biax = eps !== null && num(p.E) !== null && num(p.nu) !== null && p.nu < 0.99 ? p.E / (1 - p.nu) * eps : null;
  if (eps === null) W.push('Thermal-mismatch strain not evaluated: the expansion coefficient of the material or of the substrate is not in the library.');
  const elAlt = a => { const g = formulaOf(a.x), h = g ? safeParse(g) : null; return h ? Object.keys(h.atoms) : []; }, cleaner = alts.filter(a => { const e = elAlt(a); const nc = e.filter(z => CRM[z] && z !== 'C').length, n0 = crm.filter(z => z !== 'C').length; return e.length && !e.some(z => HAZ[z]) && (haz.length ? nc <= n0 : nc < n0); });
  const show = alts.slice(0, 15), eq = [{ kind: 'formula', label: 'Tolerance band', text: `|P_alt − P_ref|/|P_ref| ≤ ${F(tol, 3)} for each property available in both records` }, { kind: 'formula', label: 'Supply-risk mass fraction', text: 'w_CRM = Σ_{i ∈ CRM} nᵢAᵢ/M' }, { kind: 'constitutive', label: 'Thermal-mismatch strain and biaxial film stress', text: 'ε = (α_substrate − α_film)·ΔT;  σ = E/(1 − ν)·ε' }];
  if (q) eq.push({ kind: 'formula', label: 'Composition screened', text: `${chem.prettyFormula(f)}:  ${els.map(e => `${e} ${F(100 * EL[e].mass * q.atoms[e] / M, 4)} wt %${CRM[e] ? ' [CRM]' : ''}${HAZ[e] ? ' [hazard]' : ''}`).join(', ')}` });
  const syn = (m.synthesis || []).find(s => s.reaction); if (syn) { try { const fx = l => l.map(z => ({ f: z.f, phase: z.phase || '' })); eq.push({ kind: 'chemical', label: `Route whose precursors carry the supply risk: ${syn.route}`, text: chem.ionicEquations(fx(syn.reaction.reactants), fx(syn.reaction.products)).molecular }); } catch { /* skip */ } }
  return {
    summary: `For ${m.name}, ${alts.length} library alternatives (${scope}) were compared on ${keys.length} properties with a ±${F(100 * tol, 3)} % band: ${full.length} ${full.length === 1 ? 'lies' : 'lie'} within the band on every comparable property${show.length ? `, the closest being ${show[0].x.name} (${show[0].inb} of ${show[0].cmp} in band)` : ''}. ${q ? `The composition contains ${crm.length ? `critical raw materials ${crm.join(', ')} (${F(100 * wCrm, 4)} wt %)` : 'no element on the critical-raw-material screening list'} and ${haz.length ? `hazard-flagged elements ${haz.join(', ')}` : 'no hazard-flagged element'}.` : 'No elemental screening is possible without a formula.'} ${eps !== null ? `On ${sub.name} a temperature change of ${F(dT, 4)} K gives a mismatch strain of ${F(eps, 3)}${biax !== null ? ` and a biaxial stress of ${F(biax, 3)} Pa` : ''}.` : ''}`,
    kpis: [
      kp('n_alt', 'Alternatives compared', alts.length, '', `Library entries of the ${scope} sharing at least one comparable property with the reference material.`),
      kp('n_full', 'Alternatives within the band on all properties', full.length, '', 'Candidates whose every comparable property lies within the tolerance band; a property missing from either record is not compared and therefore not a proof of equivalence.', full.length > 0),
      kp('best', 'Closest alternative', show.length ? show[0].x.name : 'none', '', 'Alternative with the highest share of properties in band and, among equals, the smallest mean relative deviation.'),
      kp('dist', 'Mean deviation of the closest alternative', show.length && Number.isFinite(show[0].dist) ? show[0].dist : 0, '–', 'Mean absolute relative difference over the comparable properties; 0.1 means the properties differ by 10 % on average.', show.length ? show[0].dist < tol : null),
      kp('n_crm', 'Critical raw materials in the formula', crm.length, '', `Number of constituent elements on the screening list${crm.length ? ` (${crm.map(e => `${e}: ${CRM[e]}`).join('; ')})` : ''}. The list reflects supply risk and economic importance, not scarcity alone.`, crm.filter(e => e !== 'C').length === 0),
      kp('w_crm', 'Mass fraction of critical raw materials', wCrm, '–', 'Share of the formula mass made up of listed elements (carbon excluded, as it is only critical when sourced as natural graphite).', wCrm < 0.2),
      kp('n_haz', 'Hazard-flagged elements', haz.length, '', `Elements with restricted or highly toxic compounds${haz.length ? ` (${haz.map(e => `${e}: ${HAZ[e]}`).join('; ')})` : ''}; element-based screening only.`, haz.length === 0),
      kp('w_haz', 'Mass fraction of hazard-flagged elements', wHaz, '–', 'Share of the formula mass made up of hazard-flagged elements; relevant for substance-restriction thresholds, which are concentration limits in the homogeneous material.', wHaz === 0),
      kp('eps', 'Thermal-mismatch strain on the substrate', eps ?? 0, '–', `(α_substrate − α_material)·ΔT for a film or particle bonded to ${sub.name}; positive values put the material in tension on heating (0 when not evaluated).`, eps === null ? null : Math.abs(eps) < 2e-3),
      kp('sig', 'Biaxial mismatch stress', biax ?? 0, 'Pa', 'E/(1−ν)·ε for a thin, fully constrained film; compare with the strength of the film and of the interface (0 when not evaluated).', biax === null || num(p.yield) === null ? null : Math.abs(biax) < p.yield),
    ],
    series: [
      { key: 'band', title: 'Share of properties within the tolerance band', xlabel: 'alternative number (order of the table)', ylabel: 'fraction in band', lines: [{ name: 'in band / comparable', x: show.length ? show.map((_, i) => i + 1) : [1], y: show.length ? show.map(a => a.inb / a.cmp) : [0] }, { name: 'mean relative deviation', x: show.length ? show.map((_, i) => i + 1) : [1], y: show.length ? show.map(a => Math.min(a.dist, 5)) : [0], dash: true }], explain: 'For each listed alternative, the fraction of comparable properties inside the band and the mean relative deviation (clipped at 5). Candidates on the left are the closest drop-in substitutes on library data.' },
      { key: 'mis', title: 'Thermal-mismatch strain versus temperature change', xlabel: 'ΔT (K)', ylabel: 'mismatch strain (10⁻³)', lines: [{ name: `on ${sub.name.slice(0, 24)}`, x: [0, Math.max(dT, 1)], y: [0, eps === null ? 0 : 1e3 * eps * Math.max(dT, 1) / (dT || 1)] }, ...show.slice(0, 3).filter(a => num(a.x.props.cte) !== null && aS !== null).map(a => ({ name: a.x.name.slice(0, 24), x: [0, Math.max(dT, 1)], y: [0, 1e3 * (aS - a.x.props.cte) * Math.max(dT, 1)], dash: true }))], explain: 'Mismatch strain against the chosen substrate for the reference material and the closest alternatives with expansion data. A substitute with a different slope changes residual stress and the risk of cracking or delamination.' },
    ],
    tables: [
      { key: 'alts', title: 'Alternatives', columns: ['Alternative', 'In band', 'Mean deviation', 'Deviations', 'CRM elements', 'Hazard elements'], rows: show.length ? show.map(a => { const e = elAlt(a); return [a.x.name, `${a.inb} of ${a.cmp}`, F(a.dist, 3), a.det.join('; '), e.filter(z => CRM[z]).join(', ') || (e.length ? 'none' : 'n.d.'), e.filter(z => HAZ[z]).join(', ') || (e.length ? 'none' : 'n.d.')]; }) : [['none', '–', '–', '–', '–', '–']], explain: 'Candidate substitutes ordered by closeness, with the relative deviation of each comparable property and their own critical-raw-material and hazard flags.' },
      { key: 'elements', title: 'Elemental screening of the reference material', columns: ['Element', 'Mass fraction (%)', 'Critical raw material', 'Hazard flag'], rows: q ? els.map(e => [e, F(100 * EL[e].mass * q.atoms[e] / M, 4), CRM[e] || 'not listed', HAZ[e] || 'none']) : [['–', '–', 'no formula', 'no formula']], explain: 'Constituent elements against the screening lists. "Screening list; verify current official list": listings change with each revision and differ between jurisdictions.' },
      { key: 'compat', title: 'Compatibility notes', columns: ['Aspect', 'Note'], rows: [['Thermal mismatch', eps === null ? 'not evaluated (expansion data missing)' : `ε = ${F(eps, 3)} on ${sub.name} for ΔT = ${F(dT, 4)} K${biax !== null ? `; σ = ${F(biax, 3)} Pa (${biax > 0 ? 'tensile' : 'compressive'} in the material)` : ''}`], ['Process temperature', (m.synthesis || [])[0] && m.synthesis[0].T_C ? `library route at ${m.synthesis[0].T_C.join('–')} °C; substrate melting point ${num(sp.melting_K) === null ? 'n.d.' : F(sp.melting_K - 273.15, 4) + ' °C'}` : 'no route temperature recorded'], ['Handling', (m.hazards || []).join('; ') || 'no hazard note recorded'], ['Class caveat', (findClass(m.classId) || {}).caveats || 'none recorded']], explain: 'Quantified thermal-mismatch compatibility with the selected substrate and the qualitative process, handling and class caveats recorded in the library.' },
    ],
    equations: eq,
    checks: [
      { name: 'Comparable properties available', pass: keys.length >= 2, detail: `${keys.length} reference properties usable for comparison` },
      { name: 'At least one full in-band alternative', pass: full.length > 0, detail: `${full.length} of ${alts.length}` },
      { name: 'No hazard-flagged element', pass: haz.length === 0 && !!q, detail: q ? (haz.join(', ') || 'none') : 'no formula to screen' },
      { name: 'Critical-raw-material mass fraction below 20 %', pass: !!q && wCrm < 0.2, detail: q ? pct(wCrm) : 'no formula to screen' },
      { name: 'Mismatch strain below 0.2 %', pass: eps !== null && Math.abs(eps) < 2e-3, detail: eps === null ? 'not evaluated' : F(eps, 3) },
    ],
    warnings: W,
    recommendations: [
      { priority: 'high', text: show.length ? `Qualify ${show[0].x.name} as second source: ${show[0].inb} of ${show[0].cmp} comparable properties are within ±${F(100 * tol, 3)} % (${show[0].det.slice(0, 3).join('; ')}). Test the properties that were not comparable before approving the substitution.` : 'No comparable alternative exists in the library class; widen the search with the ranking mode of suite 1.', basis: 'Tolerance-band comparison on library data.' },
      { priority: haz.length ? 'high' : 'medium', text: haz.length ? `Substitute or justify the hazard-flagged element${haz.length > 1 ? 's' : ''} ${haz.join(', ')}${cleaner.length ? `: ${cleaner[0].x.name} avoids them without adding critical raw materials` : ''}; check concentration limits of the applicable substance restrictions and plan containment and waste treatment.` : crm.filter(e => e !== 'C').length ? `Reduce dependence on ${crm.filter(e => e !== 'C').join(', ')} (${pct(wCrm)} of the mass): ${cleaner.length ? `${cleaner[0].x.name} is a lower-risk alternative in the library` : 'no lower-risk alternative is in this class, so secure recycling or dual sourcing'}.` : 'The composition is free of flagged elements on the screening lists; keep this advantage when selecting dopants and precursors.', basis: 'Element-based critical-raw-material and hazard screening.', sustainability: true },
      { priority: 'medium', text: eps !== null ? (Math.abs(eps) > 2e-3 ? `Mismatch strain ${F(eps, 3)} exceeds 0.2 %: add a compliant or graded interlayer, lower the process temperature or choose a substrate with an expansion coefficient nearer ${F(aM, 3)} /K.` : `Thermal mismatch with ${sub.name} is moderate (${F(eps, 3)}); verify adhesion after thermal cycling.`) : 'Measure the expansion coefficient of the material and substrate to assess thermal-mismatch stress.', basis: 'Thermal-mismatch strain against the chosen substrate.' },
      { priority: 'low', text: 'Re-run the comparison with supplier data sheets of the actual grades: library values are typical and the tolerance band should reflect the property scatter that the design can accept.', basis: 'Typical-value nature of the library.' },
    ],
    publish: basePublish(m, { 'risk.crm_mass_fraction': wCrm, 'risk.hazard_elements': haz.length, 'risk.n_substitutes': full.length, ...(eps !== null ? { 'mech.mismatch_strain': eps } : {}) }),
    numerics: { method: 'Tolerance-band comparison within the library class; element-based screening against critical-raw-material and hazard lists; thin-film thermal-mismatch relation', dof: pool.length, steps: keys.length, iterations: 1, residual: 0, notes: 'Properties missing from either record are excluded from the comparison.' },
  };
}

const M_ = m => ({ mode: [m] });
const inputs = [
  { key: 'mode', label: 'Analysis', type: 'select', value: 'formula', group: 'Model', options: [{ value: 'formula', label: 'Formula analysis and stoichiometry' }, { value: 'doping', label: 'Doping and solid solutions' }, { value: 'mixture', label: 'Mixture / composite property estimates' }, { value: 'alloy', label: 'Alloy / multicomponent thermodynamic screening' }, { value: 'subst', label: 'Substitution and supply risk' }, { value: 'props', label: 'Property table for downstream solvers' }], help: 'Selects the composition task. Formula, substitution and property-table modes work on the selected library material; doping, mixture and alloy modes use their own composition inputs.' },
  { key: 'matId', label: 'Library material', type: 'select', value: 'zno-nanoparticles', group: 'Material', showIf: { mode: ['formula', 'subst', 'props'] }, options: matOpts, help: 'Entry of the materials library whose formula, synthesis reaction and properties are analysed and published to the other suites.' },
  { key: 'formula', label: 'Formula (optional, overrides the library)', type: 'text', value: '', group: 'Formula', showIf: M_('formula'), help: 'Any chemical formula, for example Zn(NO3)2·6H2O or BaTiO3. Leave empty to analyse the library material. Ions may be written as SO4^2- or Zn2+.' },
  { key: 'rxnSrc', label: 'Synthesis reaction', type: 'select', value: 'library', group: 'Formula', showIf: M_('formula'), options: [{ value: 'library', label: 'Library route of the selected material' }, { value: 'user', label: 'Typed reactants and products' }], help: 'Source of the reaction used for precursor amounts. A typed formula always uses the typed reaction.' },
  { key: 'rxn', label: 'Typed reaction (unbalanced)', type: 'text', value: 'Zn(NO3)2(aq) + NaOH(aq) -> ZnO(s) + NaNO3(aq) + H2O(l)', group: 'Formula', showIf: M_('formula'), help: 'Reactants and products separated by " + " and "->", with optional phase labels (s), (l), (g), (aq). Coefficients are found automatically by element and charge balance.' },
  { key: 'targetMass', label: 'Target product mass', unit: 'g', value: 10, min: 1e-6, max: 1e7, log: true, group: 'Formula', showIf: M_('formula'), help: 'Mass of isolated product required from the batch; precursor amounts scale in proportion.' },
  { key: 'yieldPct', label: 'Expected isolated yield', unit: '%', value: 85, min: 1, max: 100, group: 'Formula', showIf: M_('formula'), help: 'Fraction of the theoretical product actually recovered after reaction, washing and drying; the batch is scaled up to compensate.' },
  { key: 'excess', label: 'Excess of non-limiting reagents', unit: '%', value: 10, min: 0, max: 500, group: 'Formula', showIf: M_('formula'), help: 'Stoichiometric excess applied to every reagent except the first, which is taken as limiting. Excess drives conversion but adds to the waste.' },
  { key: 'purity', label: 'Precursor purity', unit: '%', value: 99, min: 10, max: 100, group: 'Formula', showIf: M_('formula'), help: 'Assay of the weighed precursors; the weighed mass is the stoichiometric mass divided by the purity.' },
  // doping
  { key: 'hostF', label: 'Host formula', type: 'text', value: 'ZnO', group: 'Doping', showIf: M_('doping'), bus: 'material.formula', help: 'Formula of the host compound into which the dopant substitutes.' },
  { key: 'hostSite', label: 'Substituted host element', type: 'text', value: 'Zn', group: 'Doping', showIf: M_('doping'), help: 'Element of the host whose sites the dopant occupies.' },
  { key: 'dopant', label: 'Dopant element', type: 'text', value: 'Al', group: 'Doping', showIf: M_('doping'), help: 'Element symbol of the substitutional dopant or alloying element.' },
  { key: 'dopConc', label: 'Dopant concentration', value: 2, min: 1e-6, max: 1e22, log: true, group: 'Doping', showIf: M_('doping'), help: 'Concentration in the unit chosen below. For atoms per cm³ enter the number density directly, for example 1e20.' },
  { key: 'dopUnit', label: 'Concentration unit', type: 'select', value: 'site', group: 'Doping', showIf: M_('doping'), options: [{ value: 'site', label: 'mol % of the substituted site (100·x)' }, { value: 'at', label: 'at % of all atoms' }, { value: 'wt', label: 'wt % of dopant element' }, { value: 'cm3', label: 'atoms per cm³' }], help: 'Basis of the stated concentration. All other units are derived from it through the site fraction x.' },
  { key: 'hostVal', label: 'Valence of the host cation', value: 2, min: 1, max: 6, step: 1, group: 'Doping', showIf: M_('doping'), help: 'Formal charge of the substituted host ion (2 for Zn in ZnO, 4 for Ti in TiO₂).' },
  { key: 'dopVal', label: 'Valence of the dopant', value: 3, min: 1, max: 6, step: 1, group: 'Doping', showIf: M_('doping'), help: 'Formal charge of the dopant ion on the host site (3 for Al³⁺). Higher than the host gives a donor, lower an acceptor.' },
  { key: 'hostRho', label: 'Host density', unit: 'kg/m³', value: 5606, min: 100, max: 25000, group: 'Doping', showIf: M_('doping'), bus: 'prop.density', help: 'Crystal density of the undoped host, used for number densities.' },
  { key: 'aHost', label: 'Host lattice parameter', unit: 'Å', value: 3.250, min: 1, max: 30, step: 0.001, group: 'Doping', showIf: M_('doping'), help: 'Lattice parameter of the undoped host (a = 3.250 Å for wurtzite ZnO).' },
  { key: 'aEnd', label: 'End-member lattice parameter', unit: 'Å', value: 3.11, min: 1, max: 30, step: 0.001, group: 'Doping', showIf: M_('doping'), help: 'Lattice parameter of the fully substituted compound in the same structure type (real or hypothetical), the second anchor of Vegard’s law. The default is an illustrative value for a wurtzite-type end member.' },
  { key: 'abx', label: 'Perovskite formula for the tolerance factor', type: 'text', value: 'BaTiO3', group: 'Doping', showIf: M_('doping'), help: 'ABX₃ formula whose Goldschmidt tolerance factor is evaluated with the built-in Shannon radii, for example SrTiO3, CaTiO3, CsPbBr3.' },
  // mixture
  { key: 'm1', label: 'Constituent 1 (matrix)', type: 'select', value: 'epoxy', group: 'Mixture', showIf: M_('mixture'), options: matOpts, help: 'First constituent, treated as the continuous phase in the Maxwell–Eucken estimate and as the swept phase in the charts.' },
  { key: 'm2', label: 'Constituent 2', type: 'select', value: 'alumina', group: 'Mixture', showIf: M_('mixture'), options: matOpts, help: 'Second constituent (filler, reinforcement or second phase).' },
  { key: 'm3', label: 'Constituent 3', type: 'select', value: 'none', group: 'Mixture', showIf: M_('mixture'), options: [{ value: 'none', label: 'none (two-constituent system)' }, ...matOpts], help: 'Optional third constituent; its volume fraction is the remainder.' },
  { key: 'vf1', label: 'Volume fraction of constituent 1', value: 0.7, min: 0.001, max: 0.999, step: 0.01, group: 'Mixture', showIf: M_('mixture'), help: 'Volume fraction of the first constituent in the pore-free mixture.' },
  { key: 'vf2', label: 'Volume fraction of constituent 2 (three-constituent system)', value: 0.2, min: 0.001, max: 0.999, step: 0.01, group: 'Mixture', showIf: M_('mixture'), help: 'Used only when a third constituent is selected; in a two-constituent system the second fraction is the remainder.' },
  { key: 'rhoMeas', label: 'Measured bulk density', unit: 'kg/m³', value: 0, min: 0, max: 25000, group: 'Mixture', showIf: M_('mixture'), help: 'Measured density of the consolidated mixture; with the theoretical density it gives the porosity. Zero means not measured.' },
  // alloy
  { key: 'alloyText', label: 'Alloy composition (element:molar ratio)', type: 'text', value: 'Co:1, Cr:1, Fe:1, Mn:1, Ni:1', group: 'Alloy', showIf: M_('alloy'), help: 'Comma-separated elements with molar ratios, for example "Al:0.5, Co:1, Cr:1, Fe:1, Ni:1". Ratios are normalised to atom fractions.' },
  { key: 'Talloy', label: 'Temperature', unit: 'K', value: 1273, min: 200, max: 4000, group: 'Alloy', showIf: M_('alloy'), help: 'Temperature at which the mixing Gibbs energy is evaluated, for example the homogenisation temperature.' },
  { key: 'omega', label: 'Mean pair interaction parameter Ω', unit: 'kJ/mol', value: -10, min: -200, max: 200, group: 'Alloy', showIf: M_('alloy'), help: 'Regular-solution interaction parameter applied to every pair, ΔH_mix = Σ Ω·xᵢxⱼ. Negative values favour unlike neighbours. About −10 kJ/mol reproduces a mixing enthalpy near −4 kJ/mol for an equiatomic five-component alloy.' },
  // substitution
  { key: 'tolBand', label: 'Tolerance band on properties', unit: '± %', value: 25, min: 1, max: 200, group: 'Substitution', showIf: M_('subst'), help: 'Relative deviation from the reference material within which a property of an alternative counts as equivalent.' },
  { key: 'subId', label: 'Substrate / mating material', type: 'select', value: 'silicon', group: 'Substitution', showIf: M_('subst'), options: MATERIALS.filter(m => m.kind === 'constituent').map(m => ({ value: m.id, label: m.name })), help: 'Material to which the selected material is bonded, for the thermal-mismatch compatibility estimate.' },
  { key: 'dT', label: 'Temperature change', unit: 'K', value: 100, min: 0, max: 1500, group: 'Substitution', showIf: M_('subst'), help: 'Temperature excursion (process to service, or service range) over which the thermal-mismatch strain develops.' },
];

export default {
  id: 2,
  tagline: 'Analyses formulae, stoichiometry, doping, mixtures and alloys, screens substitutes and supply risk, and publishes the property table used by the other suites.',
  inputs,
  presets: [
    { name: 'ZnO nanoparticles: precipitation stoichiometry', note: 'Zinc nitrate + sodium hydroxide route: precursor amounts for 10 g ZnO, ionic equations, atom economy and E-factor.', values: { mode: 'formula', matId: 'zno-nanoparticles', rxnSrc: 'library', targetMass: 10, yieldPct: 85, excess: 10 } },
    { name: 'ZnO nanorods: hydrothermal net ionic route', note: 'Library route of hydrothermal ZnO nanorods written as the net ionic reaction of Zn²⁺ with OH⁻.', values: { mode: 'formula', matId: 'zno-nanorods', rxnSrc: 'library', targetMass: 1, yieldPct: 60, excess: 20 } },
    { name: 'Al-doped ZnO (AZO) transparent conductor', note: '2 % Al on the Zn site: donor doping with electronic compensation, the basis of a negative-permittivity (plasmonic) oxide in the near infrared.', values: { mode: 'doping', hostF: 'ZnO', hostSite: 'Zn', dopant: 'Al', dopConc: 2, dopUnit: 'site', hostVal: 2, dopVal: 3, hostRho: 5606, aHost: 3.250, aEnd: 3.11, abx: 'BaTiO3' } },
    { name: 'Yttria-stabilised zirconia', note: 'Acceptor doping of ZrO₂ with 8 mol % Y on the Zr site: oxygen-vacancy compensation.', values: { mode: 'doping', hostF: 'ZrO2', hostSite: 'Zr', dopant: 'Y', dopConc: 8, dopUnit: 'site', hostVal: 4, dopVal: 3, hostRho: 5680, aHost: 5.07, aEnd: 5.30, abx: 'SrTiO3' } },
    { name: 'Zero-expansion composite: ZrW₂O₈ in copper', note: 'Negative-thermal-expansion filler in a copper matrix: Turner estimate of the zero-expansion composition.', values: { mode: 'mixture', m1: 'zrw2o8', m2: 'copper', m3: 'none', vf1: 0.5 } },
    { name: 'Alumina-filled epoxy for a metamaterial substrate', note: 'Thermally conductive dielectric substrate: stiffness, conductivity and expansion bounds at 30 vol % filler.', values: { mode: 'mixture', m1: 'epoxy', m2: 'alumina', m3: 'none', vf1: 0.7, rhoMeas: 1950 } },
    { name: 'CoCrFeMnNi high-entropy alloy', note: 'Equiatomic Cantor alloy for metallic lattice struts: entropy, δ, VEC and Ω screening.', values: { mode: 'alloy', alloyText: 'Co:1, Cr:1, Fe:1, Mn:1, Ni:1', Talloy: 1273, omega: -10 } },
    { name: 'CdSe quantum dots: substitution and hazard screening', note: 'Cadmium-containing quantum dots compared with other library quantum dots within a ±40 % band.', values: { mode: 'subst', matId: 'cdse-qd', tolBand: 40, subId: 'fused-silica', dT: 150 } },
    { name: 'Re-entrant auxetic honeycomb: property table', note: 'Constituent and effective properties of an auxetic lattice published for the mechanics suites.', values: { mode: 'props', matId: 'reentrant-honeycomb' } },
  ],
  run(inp, ctx) {
    const r = ({ formula: runFormula, doping: runDoping, mixture: runMixture, alloy: runAlloy, subst: runSubst, props: runProps }[inp.mode] || runFormula)(inp, ctx);
    for (const k of r.kpis) if (typeof k.value === 'number' && !Number.isFinite(k.value)) { r.warnings.push(`${k.label} could not be evaluated for these inputs and is reported as 0.`); k.value = 0; k.good = null; }
    r.series = (r.series || []).map(s => ({ ...s, lines: s.lines.map(l => { const x = [], y = []; for (let i = 0; i < l.x.length; i++) if (Number.isFinite(l.x[i]) && Number.isFinite(l.y[i]) && (!s.logy || l.y[i] > 0) && (!s.logx || l.x[i] > 0)) { x.push(l.x[i]); y.push(l.y[i]); } return { ...l, x, y }; }).filter(l => l.x.length) })).filter(s => s.lines.length);
    for (const k of Object.keys(r.publish)) if (typeof r.publish[k] === 'number' && !Number.isFinite(r.publish[k])) delete r.publish[k];
    return r;
  },
};
